from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = Path("notes")


def resolve_note(name: str) -> Path | None:
    """Return the absolute path of note `name` inside NOTES_DIR, or None if it escapes.

    Absolute names, names with parent-directory components that leave NOTES_DIR,
    and symlinks whose target lies outside NOTES_DIR all yield None.
    The file need not exist.
    """
    try:
        base = (Path.cwd() / NOTES_DIR).resolve()
        candidate = (base / name).resolve()
    except (OSError, ValueError):
        return None
    if candidate.is_relative_to(base):
        return candidate
    return None


def load_note(name: str) -> str | None:
    """Return the text of note `name`, or None if it cannot be read.

    None covers: name outside NOTES_DIR, missing file, directory, permission
    error, or decode error. An empty file returns "".
    """
    path = resolve_note(name)
    if path is None:
        return None
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def count_readable(names: list[str]) -> int:
    """Count the entries of `names` for which load_note returns text.

    Each entry is counted separately, so duplicates count more than once.
    """
    return sum(1 for n in names if load_note(n) is not None)


@pytest.fixture
def notes_cwd(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_resolve_note_inside(notes_cwd: Path) -> None:
    result = resolve_note("a.txt")
    assert result is not None
    assert result.name == "a.txt"
    assert result.is_relative_to((notes_cwd / "notes").resolve())


def test_resolve_note_rejects_traversal(notes_cwd: Path) -> None:
    assert resolve_note("../secret.txt") is None
    assert resolve_note("sub/../../secret.txt") is None


def test_resolve_note_rejects_absolute(notes_cwd: Path) -> None:
    assert resolve_note("/etc/passwd") is None


def test_resolve_note_rejects_symlink_escape(notes_cwd: Path) -> None:
    outside = notes_cwd / "secret.txt"
    outside.write_text("secret", encoding="utf-8")
    (notes_cwd / "notes" / "link.txt").symlink_to(outside)
    assert resolve_note("link.txt") is None


def test_load_note_reads_text(notes_cwd: Path) -> None:
    (notes_cwd / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert load_note("a.txt") == "hello"


def test_load_note_empty_file_is_text(notes_cwd: Path) -> None:
    (notes_cwd / "notes" / "empty.txt").write_text("", encoding="utf-8")
    assert load_note("empty.txt") == ""


def test_load_note_missing_is_none(notes_cwd: Path) -> None:
    assert load_note("missing.txt") is None


def test_load_note_directory_is_none(notes_cwd: Path) -> None:
    (notes_cwd / "notes" / "sub").mkdir()
    assert load_note("sub") is None


def test_load_note_traversal_never_reads_outside(notes_cwd: Path) -> None:
    (notes_cwd / "secret.txt").write_text("secret", encoding="utf-8")
    assert load_note("../secret.txt") is None


def test_count_readable_mixed(notes_cwd: Path) -> None:
    notes = notes_cwd / "notes"
    (notes / "a.txt").write_text("x", encoding="utf-8")
    (notes / "empty.txt").write_text("", encoding="utf-8")
    (notes / "sub").mkdir()
    assert count_readable(["a.txt", "empty.txt", "missing.txt", "sub"]) == 2


def test_count_readable_ignores_traversal(notes_cwd: Path) -> None:
    (notes_cwd / "secret.txt").write_text("secret", encoding="utf-8")
    assert count_readable(["../secret.txt", "/etc/passwd"]) == 0


def test_count_readable_counts_duplicates(notes_cwd: Path) -> None:
    (notes_cwd / "notes" / "a.txt").write_text("x", encoding="utf-8")
    assert count_readable(["a.txt", "a.txt"]) == 2


def test_count_readable_empty_list(notes_cwd: Path) -> None:
    assert count_readable([]) == 0
